a<-commandArgs(TRUE)[1];t<-readRDS(file.path(a,'target_fit_details.private.rds'));rows<-list();z<-qnorm(.975)
for(v in c('g0','g1','g2')) for(enc in c('01','02')) { b<-t[[paste(v,enc,'Firth',sep='_')]]; n<-names(b$coef); V<-b$var; Cs<-if(enc=='01')list(female=c(1,0),male_carrier=c(1,1),constraint_01=c(0,1),constraint_02=c(-1,1)) else list(female=c(1,0),male_carrier=c(2,2),constraint_01=c(1,2),constraint_02=c(0,2)); for(label in names(Cs)){l<-rep(0,length(n));l[match(c('g','gs'),n)]<-Cs[[label]];e<-sum(l*b$coef);se<-sqrt(drop(t(l)%*%V%*%l));p<-2*pnorm(-abs(e/se));rows[[length(rows)+1]]<-data.frame(target=v,encoding=enc,contrast=label,beta=e,se=se,OR=exp(e),lo=exp(e-z*se),hi=exp(e+z*se),p=p,bonferroni_6=if(grepl('constraint',label))min(1,6*p) else NA)}}
o<-do.call(rbind,rows);write.csv(o,file.path(a,'verified_contrasts_both_encodings.csv'),row.names=FALSE);q<-merge(o[o$encoding=='01',],o[o$encoding=='02',],by=c('target','contrast'));cat('MAX CROSS CODING beta/SE/P discrepancy:',max(abs(q$beta.x-q$beta.y)),max(abs(q$se.x-q$se.y)),max(abs(q$p.x-q$p.y)),'\n');print(o[o$encoding=='01',c('target','contrast','OR','lo','hi','p','bonferroni_6')],row.names=FALSE)
